import { logger } from '../logger';

const SENSITIVE_HEADERS = new Set(['authorization', 'proxy-authorization', 'cookie', 'set-cookie', 'x-api-key']);

function redactHeaders(headers: Record<string, string> = {}) {
  return Object.fromEntries(
    Object.entries(headers).map(([name, value]) => [
      name,
      SENSITIVE_HEADERS.has(name.toLowerCase()) ? '[REDACTED]' : value,
    ]),
  );
}

export function logRequest(options: { headers?: Record<string, string>; url: string }) {
  logger.debug(`request url: ${options.url}`);
  logger.debug(`request headers: ${JSON.stringify(redactHeaders(options.headers))}`);
}

import { logRequest } from '../../src/http/debugLogger';
import { logger } from '../../src/logger';

jest.mock('../../src/logger', () => ({ logger: { debug: jest.fn() } }));

describe('debugLogger', () => {
  beforeEach(() => jest.clearAllMocks());

  it('redacts credential-bearing headers without logging their values', () => {
    logRequest({
      url: 'https://api.stripe.com/v1/customers',
      headers: {
        Authorization: 'Bearer rk_live_example',
        'X-Api-Key': 'secret-example',
        Accept: 'application/json',
      },
    });

    const output = (logger.debug as jest.Mock).mock.calls.flat().join(' ');
    expect(output).not.toContain('rk_live_example');
    expect(output).not.toContain('secret-example');
    expect(output).toContain('[REDACTED]');
    expect(output).toContain('application/json');
  });
});

