python3 - <<'PY'
from pathlib import Path
p = Path('src/paymentWebhook.js')
s = p.read_text()
s = s.replace("await paymentClient.deliver(event);", "await deliverWithRetry(() => paymentClient.deliver(event), { retries: 3, baseDelayMs: 250 });")
s = s.replace("module.exports = { handleWebhook };", "async function deliverWithRetry(operation, { retries, baseDelayMs }) {\n  let lastError;\n  for (let attempt = 0; attempt <= retries; attempt++) {\n    try { return await operation(); }\n    catch (error) {\n      lastError = error;\n      if (!error.transient || attempt === retries) throw error;\n      await new Promise(resolve => setTimeout(resolve, baseDelayMs * (2 ** attempt)));\n    }\n  }\n  throw lastError;\n}\n\nmodule.exports = { handleWebhook, deliverWithRetry };")
p.write_text(s)
PY
cat >> test/paymentWebhook.test.js <<'EOF'

test('retries transient delivery failures before succeeding', async () => {
  let attempts = 0;
  const { deliverWithRetry } = require('../src/paymentWebhook');
  const result = await deliverWithRetry(async () => {
    attempts += 1;
    if (attempts < 3) {
      const error = new Error('temporary provider outage');
      error.transient = true;
      throw error;
    }
    return 'delivered';
  }, { retries: 3, baseDelayMs: 1 });
  expect(result).toBe('delivered');
  expect(attempts).toBe(3);
});
EOF
