const { S3Client } = require('@aws-sdk/client-s3');

function createAwsClient() {
  const { AWS_REGION, AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY } = process.env;
  if (!AWS_REGION || !AWS_ACCESS_KEY_ID || !AWS_SECRET_ACCESS_KEY) {
    throw new Error('AWS runtime environment variables are required');
  }
  return new S3Client({
    region: AWS_REGION,
    credentials: {
      accessKeyId: AWS_ACCESS_KEY_ID,
      secretAccessKey: AWS_SECRET_ACCESS_KEY
    }
  });
}

module.exports = { createAwsClient };
EOF
cat > config/dev.env.example <<'EOF'
AWS_REGION=us-east-1
AWS_ACCESS_KEY_ID=provided-at-runtime
AWS_SECRET_ACCESS_KEY=provided-at-runtime
EOF
printf '\nconfig/dev.env\n' >> .gitignore
git rm config/dev.env

