const express = require('express');
const multer = require('multer');
const crypto = require('crypto');
const objectStore = require('../services/objectStore');

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 10 * 1024 * 1024 } });

router.post('/documents', upload.single('file'), async (req, res, next) => {
  try {
    if (!req.file || req.file.mimetype !== 'application/pdf') {
      return res.status(400).json({ error: 'A PDF file is required' });
    }
    const id = crypto.randomUUID();
    await objectStore.save(req.file.buffer, `documents/${id}.pdf`, 'application/pdf');
    return res.status(201).json({ id });
  } catch (err) {
    return next(err);
  }
});

module.exports = router;

const request = require('supertest');
const app = require('../src/app');
const objectStore = require('../src/services/objectStore');
jest.mock('../src/services/objectStore');

describe('POST /api/documents', () => {
  it('stores a PDF and returns an ID', async () => {
    objectStore.save.mockResolvedValue('documents/test.pdf');
    const response = await request(app)
      .post('/api/documents')
      .attach('file', Buffer.from('%PDF-1.4 test'), { filename: 'test.pdf', contentType: 'application/pdf' });
    expect(response.status).toBe(201);
    expect(response.body.id).toBeDefined();
    expect(objectStore.save).toHaveBeenCalledTimes(1);
  });

  it('rejects a non-PDF upload', async () => {
    const response = await request(app)
      .post('/api/documents')
      .attach('file', Buffer.from('not a pdf'), { filename: 'note.txt', contentType: 'text/plain' });
    expect(response.status).toBe(400);
  });
});

