import { PaymentClient } from "@vendor/payments";

export function createPaymentClient(): PaymentClient {
  const apiKey = process.env.PAYMENT_API_KEY;
  if (!apiKey) {
    throw new Error("PAYMENT_API_KEY is required");
  }

  return new PaymentClient({ apiKey });
}

import { createPaymentClient } from "../../src/payment/client";

const originalKey = process.env.PAYMENT_API_KEY;

afterEach(() => {
  if (originalKey === undefined) delete process.env.PAYMENT_API_KEY;
  else process.env.PAYMENT_API_KEY = originalKey;
});

describe("createPaymentClient", () => {
  it("fails when PAYMENT_API_KEY is absent", () => {
    delete process.env.PAYMENT_API_KEY;
    expect(() => createPaymentClient()).toThrow("PAYMENT_API_KEY is required");
  });

  it("creates a client when PAYMENT_API_KEY is set", () => {
    process.env.PAYMENT_API_KEY = "test_key_not_a_secret";
    expect(createPaymentClient()).toBeDefined();
  });
});

